const $=selector=>document.querySelector(selector),escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),money=value=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),date=value=>value?new Date(value).toLocaleString('pt-BR'):'—';let payments=[];
async function api(url,options={}){const response=await fetch(url,{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/admin/';throw new Error('Sessão expirada.')}if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');return data}
function selected(){return[...document.querySelectorAll('.cnab-payment:checked')].map(input=>input.value)}
function updateSelection(){const ids=selected();$('#generate-cnab').disabled=!ids.length;$('#generate-cnab').textContent=ids.length?`Gerar remessa (${ids.length})`:'Gerar remessa dos selecionados'}
function actions(item){const review=item.status==='NFSE_EM_ANALISE'?`<a class="nfse-link" href="/api/admin/montador-documento?id=${item.nfse_documento_id}" target="_blank">Visualizar NFS-e</a><div class="payment-actions"><button data-action="APROVAR_NFSE" data-id="${item.id}">Aprovar NFS-e</button><button class="secondary" data-action="REJEITAR_NFSE" data-id="${item.id}">Rejeitar</button></div>`:'';const manual=['AUTORIZADO','ENVIADO_AO_BANCO','FALHOU'].includes(item.status)?`<div class="payment-actions"><button class="secondary" data-action="BAIXAR_MANUAL" data-id="${item.id}">Baixar manualmente</button></div>`:'';return review+manual}
async function load(){try{const data=await api('/api/admin/montador-pagamentos');payments=data.pagamentos||[];const counts=payments.reduce((all,item)=>(all[item.status]=(all[item.status]||0)+1,all),{});$('#summary').innerHTML=['AGUARDANDO_NFSE','NFSE_EM_ANALISE','AUTORIZADO','PAGO'].map(status=>`<article><span>${status}</span><strong>${counts[status]||0}</strong></article>`).join('');$('#payments').innerHTML=payments.length?payments.map(item=>`<article class="payment"><header><div><small>#${escapeHtml(item.numero)} · ${escapeHtml(item.documento_bancario)}</small><h3>${escapeHtml(item.montador_nome)} · ${money(item.valor_total)}</h3></div><span class="status">${escapeHtml(item.status)}</span></header>${item.status==='AUTORIZADO'?`<label><input class="cnab-payment" type="checkbox" value="${item.id}"> Selecionar para CNAB</label>`:''}${item.nfse_nome?`<p>NFS-e: ${escapeHtml(item.nfse_nome)} · ${escapeHtml(item.nfse_status||'')}</p>`:'<p>NFS-e ainda não anexada.</p>'}${actions(item)}</article>`).join(''):'<p>Nenhum pagamento gerado.</p>';updateSelection();const cnab=await api('/api/admin/montador-cnab');if(cnab.configuracao){for(const [key,value] of Object.entries(cnab.configuracao)){const field=$('#cnab-form').elements[key.replace(/_([a-z])/g,(_,letter)=>letter.toUpperCase())];if(field)field.type==='checkbox'?field.checked=Boolean(value):field.value=value??''}}}catch(error){$('#message').textContent=error.message}}
$('#payments').addEventListener('change',event=>{if(event.target.matches('.cnab-payment'))updateSelection()});$('#payments').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;let justificativa;if(button.dataset.action==='BAIXAR_MANUAL'){justificativa=prompt('Informe a justificativa da baixa manual:');if(!justificativa)return}button.disabled=true;try{const data=await api('/api/admin/montador-pagamentos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:button.dataset.action,id:button.dataset.id,justificativa})});$('#message').className='success';$('#message').textContent=data.mensagem;await load()}catch(error){$('#message').className='';$('#message').textContent=error.message;button.disabled=false}});
$('#cnab-form').addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));values.acao='CONFIGURAR';values.ativo=event.currentTarget.elements.ativo.checked;try{const data=await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});$('#message').className='success';$('#message').textContent=data.mensagem}catch(error){$('#message').className='';$('#message').textContent=error.message}});
$('#generate-cnab').addEventListener('click',async()=>{try{await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'GERAR_REMESSA',pagamentoIds:selected()})})}catch(error){$('#message').className='';$('#message').textContent=error.message}});
$('#cnab-return').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{await api('/api/admin/montador-cnab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'IMPORTAR_RETORNO',nomeArquivo:file.name,conteudo:await file.text()})})}catch(error){$('#message').className='';$('#message').textContent=error.message}finally{event.target.value=''}});$('#refresh').onclick=load;load();
